import type { Eip1193Provider } from './wallet.js';
export const TX_STATE: Readonly<Record<'IDLE' | 'PREPARING' | 'AWAITING_WALLET' | 'SUBMITTED' | 'CONFIRMING' | 'CONFIRMED' | 'PRE_BROADCAST_FAILED' | 'UNKNOWN_SEND' | 'UNKNOWN_SEND_DUPLICATE' | 'AMBIGUOUS' | 'REVERTED' | 'READY' | 'AWAITING_WALLET_APPROVAL' | 'REJECTED' | 'FAILED', string>>;
export const PENDING_TX_STORAGE_KEY: string;
export const PENDING_TX_SCHEMA: string;
export const UNKNOWN_SEND_STORAGE_KEY: string;
export const UNKNOWN_SEND_SCHEMA: string;
export const AMBIGUOUS_TRANSACTION_MESSAGE: string;
export const UNKNOWN_SEND_MESSAGE: string;
export const UNKNOWN_SEND_NO_MATCH_MESSAGE: string;
export const UNKNOWN_SEND_DUPLICATE_MESSAGE: string;
export const ACCOUNT_CHANGED_MESSAGE: string;
export const CHAIN_CHANGED_MESSAGE: string;
export const UNKNOWN_RECONCILE_MAX_BLOCKS: bigint;
export const SAFE_START_BUFFER_BLOCKS: bigint;
export const DEFAULT_PROOF_WINDOW_BLOCKS: bigint;
export const HEAD_UNAVAILABLE_MESSAGE: string;
export const STALE_START_MESSAGE: string;
export const FEE_PREPARATION_MESSAGE: string;
export const FEE_DISCOVERY_MESSAGE: string;
export const SIMULATION_FAILURE_MESSAGE: string;
export const GAS_ESTIMATION_FAILURE_MESSAGE: string;
export const BASE_FEE_HEADROOM_MULTIPLIER: bigint;
export type CommitmentInput = { subject: string; minimum: string; startBlock: string; endBlock: string };
export type PendingTransaction = { schema: string; chainId: string; registry: string; txHash: string; sender: string; subject: string; token: string; minimumBalance: string; startBlock: string; endBlock: string; createdAt: number };
export type UnknownSendAttempt = { schema: string; chainId: string; registry: string; sender: string; preSendAccount: string; subject: string; token: string; minimumBalance: string; startBlock: string; endBlock: string; attemptBlock: string; preSendNonce: string | null; attemptedAt: number };
export type StorageLike = { getItem(key: string): string | null; setItem(key: string, value: string): void; removeItem(key: string): void };
export function createSubmissionGuard(): { isLocked(): boolean; run<T>(task: () => T | Promise<T>): Promise<T | { skipped: true }> };
export function buildPendingTransaction(input: CommitmentInput, account: string, txHash: string, createdAt?: number): PendingTransaction;
export function persistPendingTransaction(pending: PendingTransaction, storage?: StorageLike): boolean;
export function loadPendingTransaction(storage?: StorageLike): PendingTransaction | null;
export function clearPendingTransaction(storage?: StorageLike): void;
export function buildUnknownSendAttempt(input: CommitmentInput, account: string, attemptBlock: bigint, preSendNonce: bigint | null, attemptedAt?: number): UnknownSendAttempt;
export function persistUnknownSendAttempt(attempt: UnknownSendAttempt, storage?: StorageLike): boolean;
export function loadUnknownSendAttempt(storage?: StorageLike): UnknownSendAttempt | null;
export function clearUnknownSendAttempt(storage?: StorageLike): void;
export function pendingMatchesTerms(pending: PendingTransaction | null, input: CommitmentInput, account: string): boolean;
export function pendingMatchesWallet(pending: PendingTransaction | null, account: string | null, chainId: string | null): boolean;
export function parseMinimumBalance(value: unknown): bigint;
export function readCurrentElysiumBlock(fetchImplementation?: typeof fetch): Promise<bigint>;
export function safeStartBlock(currentHead: bigint, buffer?: bigint): bigint;
export function proofWindowEnd(startBlock: bigint, window?: bigint): bigint;
export function validateCommitmentInput(input: CommitmentInput, currentHead: bigint | null | undefined): { valid: boolean; errors: Record<string, string>; minimumBalance?: bigint; currentHead: bigint | null | undefined };
export function buildCommitmentTransaction(input: CommitmentInput, from: string, currentHead: bigint): { from: string; to: string; value: string; data: string };
export function preflightCommitment(provider: Eip1193Provider, transaction: Record<string, string>): Promise<{ gas: string }>;
export function readFreshEip1559Fees(provider: Eip1193Provider): Promise<{ maxFeePerGas: string; maxPriorityFeePerGas: string; observedBaseFeePerGas: bigint; predictedBaseFeePerGas: bigint; observedGasPrice: bigint }>;
export function waitForSuccessfulReceipt(provider: Eip1193Provider, hash: string, options?: { attempts?: number; intervalMs?: number }): Promise<any>;
export function commitmentEventFromReceipt(receipt: any): any;
export function commitmentIdFromReceipt(receipt: any): bigint;
export function readBackCommitment(provider: Eip1193Provider, id: bigint): Promise<any>;
export function commitmentMatchesPending(commitment: any, pending: PendingTransaction): boolean;
export function commitmentEventMatchesPending(event: any, pending: PendingTransaction): boolean;
export function reconcilePendingTransaction(provider: Eip1193Provider, pending: PendingTransaction, onState?: (state: string, extra?: any) => void, options?: { storage?: StorageLike }): Promise<any>;
export function reconcileUnknownSendAttempt(provider: Eip1193Provider, attempt: UnknownSendAttempt, onState?: (state: string, extra?: any) => void, options?: { storage?: StorageLike }): Promise<any>;
export type CommitmentPreparationOptions = { readHead?: () => Promise<bigint>; readFees?: (provider: Eip1193Provider) => Promise<{ maxFeePerGas: string; maxPriorityFeePerGas: string; [key: string]: unknown }>; onHead?: (head: bigint) => void; storage?: StorageLike; now?: () => number; waitForReceipt?: typeof waitForSuccessfulReceipt };
export function prepareCommitmentForWallet(provider: Eip1193Provider, input: CommitmentInput, account: string, options?: CommitmentPreparationOptions): Promise<{ transaction: Record<string, string>; fees: Record<string, unknown>; currentHead: bigint }>;
export function submitCommitment(provider: Eip1193Provider, input: CommitmentInput, account: string, onState?: (state: string, extra?: any) => void, options?: CommitmentPreparationOptions): Promise<any>;
